const i=[{id:"liver-001",topicId:"liver",question:"Чем является печень с точки зрения строения и роли в организме?",options:["Паренхиматозным органом пищеварительной системы и крупнейшей железой организма","Полым мышечным органом","Железой внутренней секреции, не связанной с пищеварением","Лимфоидным органом иммунной системы"],correctIndex:0,explanation:"Печень — паренхиматозный орган пищеварительной системы и крупнейшая железа организма.",difficulty:"medium",tags:["анатомия","определение"]},{id:"liver-002",topicId:"liver",question:"Где расположена печень?",options:["В левом подреберье над селезёнкой","В правом подреберье, под диафрагмой","В полости малого таза","В забрюшинном пространстве на уровне поясницы"],correctIndex:1,explanation:"Печень расположена в правом подреберье, под диафрагмой.",difficulty:"easy",tags:["анатомия"]},{id:"liver-003",topicId:"liver",question:"Какова средняя масса печени взрослого человека?",options:["300–500 г","70–80 г","1,5–2 кг","3–4 кг"],correctIndex:2,explanation:"Средняя масса печени взрослого человека составляет 1,5–2 кг.",difficulty:"medium",tags:["анатомия"]},{id:"liver-004",topicId:"liver",question:"Сколько долей имеет печень?",options:["Три — правую, левую и среднюю","Четыре","Одну неразделённую","Две — правую и левую"],correctIndex:3,explanation:"Печень имеет две доли: правую и левую.",difficulty:"easy",tags:["анатомия"]},{id:"liver-005",topicId:"liver",question:"Какой важной способностью обладает печень?",options:["Хорошей способностью к регенерации","Способностью к самостоятельному сокращению","Способностью вырабатывать инсулин","Способностью к газообмену"],correctIndex:0,explanation:"Печень обладает хорошей способностью к регенерации.",difficulty:"medium",tags:["физиология"]},{id:"liver-006",topicId:"liver",question:"На каких стадиях чаще всего проявляются симптомы болезни печени?",options:["На самых ранних стадиях","На поздних стадиях","Только при полном разрушении органа","Симптомы отсутствуют на всех стадиях"],correctIndex:1,explanation:"Симптомы болезни печени часто проявляются на поздних стадиях.",difficulty:"medium",tags:["симптомы"]},{id:"liver-007",topicId:"liver",question:"Какие изменения мочи и кала характерны для заболеваний печени?",options:["Потемнение кала и посветление мочи","И моча, и кал темнеют","Потемнение мочи и посветление кала","Никаких изменений не происходит"],correctIndex:2,explanation:"Для заболеваний печени характерны потемнение мочи и посветление кала.",difficulty:"hard",tags:["симптомы"]},{id:"liver-008",topicId:"liver",question:"Как называется увеличение живота за счёт скопления жидкости при болезнях печени?",options:["Метеоризм","Портальная гипертензия","Гепатомегалия","Асцит"],correctIndex:3,explanation:"Асцит — увеличение живота, отмечаемое при заболеваниях печени наряду с отёками.",difficulty:"medium",tags:["симптомы"]},{id:"liver-009",topicId:"liver",question:"Какие нарушения пищеварения распространены при болезнях печени?",options:["Тошнота, горечь во рту и потеря аппетита","Только запоры","Только изжога","Только повышенный аппетит"],correctIndex:0,explanation:"При болезнях печени распространены нарушения пищеварения: тошнота, горечь во рту, потеря аппетита.",difficulty:"medium",tags:["симптомы"]},{id:"liver-010",topicId:"liver",question:"Какие кожные проявления характерны для заболеваний печени?",options:["Только бледность кожи","Кожный зуд, сосудистые звёздочки и кровоподтёки","Только избыточное потоотделение","Только шелушение и сухость"],correctIndex:1,explanation:"При болезнях печени отмечаются кожный зуд, сосудистые звёздочки и кровоподтёки, а также желтуха.",difficulty:"medium",tags:["симптомы"]},{id:"liver-011",topicId:"liver",question:"Сколько основных функций выделяют у печени?",options:["Три","Пять","Семь","Десять"],correctIndex:2,explanation:"Выделяют семь основных функций печени: метаболическую, детоксикационную, пищеварительную, синтетическую, гемостатическую, выделительную и депонирующую.",difficulty:"medium",tags:["физиология","функции"]},{id:"liver-012",topicId:"liver",question:"В какое вещество печень преобразует глюкозу для создания запаса энергии?",options:["В холестерин","В мочевину","В билирубин","В гликоген"],correctIndex:3,explanation:"В рамках метаболической функции печень преобразует глюкозу в гликоген — запас энергии.",difficulty:"medium",tags:["физиология","функции"]},{id:"liver-013",topicId:"liver",question:"Какие витамины накапливает печень?",options:["A, D и B12","Только витамин C","Только витамины группы K","Только витамин E"],correctIndex:0,explanation:"Печень накапливает витамины A, D и B12, а также микроэлементы — железо и медь.",difficulty:"medium",tags:["физиология","функции"]},{id:"liver-014",topicId:"liver",question:"Какие микроэлементы накапливаются в печени?",options:["Кальций и фосфор","Железо и медь","Калий и натрий","Йод и селен"],correctIndex:1,explanation:"Печень накапливает микроэлементы железо и медь.",difficulty:"medium",tags:["физиология","функции"]},{id:"liver-015",topicId:"liver",question:"В какое вещество печень превращает аммиак в рамках детоксикационной функции?",options:["В гликоген","В билирубин","В мочевину","В холестерин"],correctIndex:2,explanation:"Детоксикационная функция печени включает превращение аммиака в мочевину.",difficulty:"hard",tags:["физиология","функции"]},{id:"liver-016",topicId:"liver",question:"Что нейтрализует печень в рамках детоксикационной функции?",options:["Только продукты распада эритроцитов","Только пищевые аллергены","Только избыток витаминов","Яды, алкоголь, лекарства и продукты метаболизма"],correctIndex:3,explanation:"Детоксикационная (обезвреживающая) функция печени состоит в нейтрализации ядов, алкоголя, лекарств и продуктов метаболизма.",difficulty:"medium",tags:["физиология","функции"]},{id:"liver-017",topicId:"liver",question:"В чём заключается пищеварительная функция печени?",options:["В производстве желчи, необходимой для расщепления жиров и всасывания питательных веществ","В выработке соляной кислоты","В синтезе пепсина","В механическом измельчении пищи"],correctIndex:0,explanation:"Пищеварительная функция печени заключается в производстве желчи, необходимой для расщепления жиров и всасывания питательных веществ.",difficulty:"medium",tags:["физиология","функции"]},{id:"liver-018",topicId:"liver",question:"Что синтезирует печень в рамках синтетической функции?",options:["Инсулин и глюкагон","Белки плазмы крови, холестерин и фосфолипиды","Соляную кислоту и пепсин","Гормоны щитовидной железы"],correctIndex:1,explanation:"Синтетическая функция печени — синтез белков плазмы крови, холестерина и фосфолипидов.",difficulty:"medium",tags:["физиология","функции"]},{id:"liver-019",topicId:"liver",question:"Что производит печень в рамках гемостатической функции?",options:["Эритроциты","Лейкоциты","Факторы свёртывания крови","Тромбоциты"],correctIndex:2,explanation:"Гемостатическая (свёртывающая) функция печени состоит в производстве факторов свёртывания крови.",difficulty:"medium",tags:["физиология","функции"]},{id:"liver-020",topicId:"liver",question:"Что удаляет печень из организма в рамках выделительной функции?",options:["Только углекислый газ","Только воду","Только минеральные соли","Избыток гормонов, билирубин и токсины"],correctIndex:3,explanation:"Выделительная функция печени — удаление из организма избытка гормонов, билирубина и токсинов.",difficulty:"medium",tags:["физиология","функции"]},{id:"liver-021",topicId:"liver",question:"Резервуаром чего служит печень в рамках депонирующей функции?",options:["Крови, гликогена, витаминов и минералов","Только желчи","Только жировой ткани","Только лимфы"],correctIndex:0,explanation:"Депонирующая (накопительная) функция печени — служить резервуаром крови, гликогена, витаминов и минералов.",difficulty:"medium",tags:["физиология","функции"]},{id:"liver-022",topicId:"liver",question:"Что такое гепатиты?",options:["Опухолевые заболевания печени","Группа воспалительных болезней печени","Замещение печёночной ткани жиром","Нарушение оттока желчи"],correctIndex:1,explanation:"Гепатитами называют группу воспалительных болезней печени.",difficulty:"easy",tags:["гепатит","определение"]},{id:"liver-023",topicId:"liver",question:"Какими причинами может вызываться гепатит?",options:["Только вирусами","Только алкоголем","Вирусами, алкоголем, лекарствами или аутоиммунными нарушениями","Только наследственными факторами"],correctIndex:2,explanation:"Гепатит вызывается различными причинами: вирусами, употреблением алкоголя, определёнными лекарствами или аутоиммунными нарушениями.",difficulty:"medium",tags:["гепатит","этиология"]},{id:"liver-024",topicId:"liver",question:"Какие клетки повреждаются при любом виде гепатита?",options:["Лимфоциты","Эритроциты","Клетки желчного пузыря","Гепатоциты"],correctIndex:3,explanation:"При любом виде гепатита повреждаются гепатоциты — печёночные клетки.",difficulty:"medium",tags:["гепатит","патогенез"]},{id:"liver-025",topicId:"liver",question:"Какое второе название имеет гепатит A?",options:["Болезнь Боткина","Болезнь Крона","Дельта-гепатит","Серозный гепатит"],correctIndex:0,explanation:"Гепатит A также называют болезнью Боткина.",difficulty:"medium",tags:["гепатит A"]},{id:"liver-026",topicId:"liver",question:"Каким путём передаётся гепатит A?",options:["Через кровь при инъекциях","Фекально-оральным путём","Половым путём","Трансмиссивным путём через укусы насекомых"],correctIndex:1,explanation:"Гепатит A передаётся фекально-оральным путём.",difficulty:"medium",tags:["гепатит A","пути передачи"]},{id:"liver-027",topicId:"liver",question:"Каков инкубационный период гепатита A?",options:["От 3 до 7 дней","От 40 до 180 дней","От 15 до 45 дней","От 15 до 150 дней"],correctIndex:2,explanation:"Время от заражения гепатитом A до появления симптомов обычно составляет от 15 до 45 дней.",difficulty:"hard",tags:["гепатит A"]},{id:"liver-028",topicId:"liver",question:"Чем в большинстве случаев завершается гепатит A?",options:["Переходом в цирроз","Развитием рака печени","Пожизненным носительством вируса","Выздоровлением без хронических последствий"],correctIndex:3,explanation:"В большинстве случаев гепатит A завершается выздоровлением без хронических последствий.",difficulty:"medium",tags:["гепатит A"]},{id:"liver-029",topicId:"liver",question:"Какие клетки полностью удаляют вирус гепатита A и инфицированные клетки из организма?",options:["Макрофаги","Эритроциты","Тромбоциты","Гепатоциты"],correctIndex:0,explanation:"Вирус гепатита A и инфицированные клетки полностью удаляются макрофагами из организма.",difficulty:"hard",tags:["гепатит A","патогенез"]},{id:"liver-030",topicId:"liver",question:"Каким вирусом провоцируется гепатит B?",options:["РНК-вирусом","ДНК-вирусом","Дефектным вирусом-спутником","Бактериофагом"],correctIndex:1,explanation:"Гепатит B провоцируется ДНК-вирусом.",difficulty:"medium",tags:["гепатит B"]},{id:"liver-031",topicId:"liver",question:"Сколько дней проходит от заражения гепатитом B до появления симптомов?",options:["От 5 до 10 дней","От 15 до 45 дней","От 40 до 180 дней","От 1 до 2 лет"],correctIndex:2,explanation:"Гепатит B имеет инкубационный период от 40 до 180 дней.",difficulty:"hard",tags:["гепатит B"]},{id:"liver-032",topicId:"liver",question:"Какими путями передаётся гепатит B?",options:["Воздушно-капельным путём","Через загрязнённую воду","Через укусы насекомых","Через кровь и половым путём"],correctIndex:3,explanation:"Гепатит B передаётся через кровь (например, при инъекциях, переливаниях) и половым путём.",difficulty:"medium",tags:["гепатит B","пути передачи"]},{id:"liver-033",topicId:"liver",question:"В каких клетках размножается вирус гепатита B?",options:["В гепатоцитах, лимфоцитах и макрофагах","Только в эритроцитах","Только в клетках желчного пузыря","Только в клетках кишечника"],correctIndex:0,explanation:"Вирус гепатита B размножается в гепатоцитах, лимфоцитах и макрофагах.",difficulty:"hard",tags:["гепатит B","патогенез"]},{id:"liver-034",topicId:"liver",question:"Какая особенность строения отличает вирус гепатита C?",options:["Он не содержит генетического материала","Это РНК-содержащий вирус с липидной оболочкой","Это ДНК-вирус без оболочки","Он состоит только из белковой капсулы"],correctIndex:1,explanation:"Гепатит C вызывается РНК-содержащим вирусом, обладающим липидной оболочкой.",difficulty:"hard",tags:["гепатит C"]},{id:"liver-035",topicId:"liver",question:"Какой промежуток времени составляет скрытый период при гепатите C?",options:["От 3 до 10 дней","От 40 до 180 дней","От 15 до 150 дней","От 6 месяцев до года"],correctIndex:2,explanation:"Инкубационный период гепатита C составляет от 15 до 150 дней.",difficulty:"hard",tags:["гепатит C"]},{id:"liver-036",topicId:"liver",question:"Почему обнаружение гепатита C затруднено?",options:["Он не вызывает никаких изменений в организме","Он не размножается в печени","Он поражает только детей","Существуют серологические реакции, но прямых маркеров нет"],correctIndex:3,explanation:"Для диагностики гепатита C существуют специальные серологические реакции, но прямых маркеров нет, что делает его обнаружение сложным.",difficulty:"hard",tags:["гепатит C","диагностика"]},{id:"liver-037",topicId:"liver",question:"К каким тяжёлым исходам может привести гепатит C?",options:["К циррозу и раку","К желчнокаменной болезни","К язвенной болезни желудка","К хроническому панкреатиту"],correctIndex:0,explanation:"Гепатит C быстро прогрессирует и может привести к циррозу и раку.",difficulty:"medium",tags:["гепатит C","осложнения"]},{id:"liver-038",topicId:"liver",question:"При каком условии развивается гепатит D?",options:["Только при одновременном заражении гепатитом A","При условии уже имеющегося антигена вируса B","Только у пациентов с гепатитом C","Независимо от других вирусов гепатита"],correctIndex:1,explanation:"Гепатит D провоцируется дефектным РНК-вирусом при условии уже имеющегося антигена вируса B.",difficulty:"hard",tags:["гепатит D"]},{id:"liver-039",topicId:"liver",question:"Буквой греческого алфавита в лекции обозначен один из гепатитов. Как звучит это название?",options:["Болезнь Боткина","Эпидемический гепатит","Дельта","Серозный гепатит"],correctIndex:2,explanation:"Гепатит D также называется дельта-гепатитом.",difficulty:"medium",tags:["гепатит D"]},{id:"liver-040",topicId:"liver",question:"Что происходит, если гепатит D присоединяется к уже имеющемуся гепатиту B?",options:["Заболевание самопроизвольно излечивается","Течение болезни не изменяется","Развивается только лёгкая острая форма","Заболевание прогрессирует вплоть до развития цирроза"],correctIndex:3,explanation:"Если заражение гепатитом D происходит на фоне уже имеющегося гепатита B, это приводит к прогрессированию заболевания вплоть до развития цирроза.",difficulty:"hard",tags:["гепатит D"]},{id:"liver-041",topicId:"liver",question:"Через что происходит заражение гепатитом E?",options:["Через загрязнённую воду или пищу, при контакте с зараженными людьми и животными","Только при переливании крови","Только половым путём","Воздушно-капельным путём"],correctIndex:0,explanation:"Гепатит E обычно передаётся через загрязнённую воду или пищу, при контакте с заражёнными людьми и животными.",difficulty:"medium",tags:["гепатит E","пути передачи"]},{id:"liver-042",topicId:"liver",question:"На что похожи симптомы гепатита E на начальной стадии?",options:["На пищевое отравление","На грипп","На аллергическую реакцию","На приступ стенокардии"],correctIndex:1,explanation:"На начальной стадии симптомы гепатита E похожи на грипп.",difficulty:"medium",tags:["гепатит E","симптомы"]},{id:"liver-043",topicId:"liver",question:"У каких пациентов гепатит E чаще переходит в хроническую форму?",options:["У детей младшего возраста","У людей пожилого возраста","У пациентов с ослабленным иммунитетом и беременных","У профессиональных спортсменов"],correctIndex:2,explanation:"Гепатит E переходит в хроническую форму у пациентов с ослабленным иммунитетом и беременных.",difficulty:"hard",tags:["гепатит E"]},{id:"liver-044",topicId:"liver",question:"Что происходит с тканью печени при циррозе?",options:["Она полностью восстанавливается","Она замещается жировой тканью обратимо","Она увеличивается в объёме без изменения структуры","Паренхиматозная ткань необратимо замещается фиброзной соединительной"],correctIndex:3,explanation:"Цирроз печени сопровождается необратимым замещением паренхиматозной ткани печени фиброзной соединительной тканью.",difficulty:"medium",tags:["цирроз","определение"]},{id:"liver-045",topicId:"liver",question:"Какие причины приводят к развитию цирроза печени?",options:["Алкоголь, вирусы гепатита, токсины, наследственные и метаболические нарушения","Только злоупотребление алкоголем","Только вирусные инфекции","Только приём лекарственных препаратов"],correctIndex:0,explanation:"Причины цирроза различны: употребление алкоголя, инфекции (вирусы гепатита), токсины, а также наследственные и метаболические нарушения.",difficulty:"medium",tags:["цирроз","этиология"]},{id:"liver-046",topicId:"liver",question:"Как называется повышение давления в венозной системе при циррозе?",options:["Артериальная гипертензия","Портальная гипертензия","Лёгочная гипертензия","Внутричерепная гипертензия"],correctIndex:1,explanation:"Цирроз может привести к повышению давления в венозной системе — портальной гипертензии.",difficulty:"medium",tags:["цирроз","осложнения"]},{id:"liver-047",topicId:"liver",question:"Как называется расширение кровеносных сосудов передней брюшной стенки при портальной гипертензии?",options:["«Сосудистые звёздочки»","«Барабанные палочки»","«Голова медузы»","«Часовые стёкла»"],correctIndex:2,explanation:"При портальной гипертензии наблюдается расширение кровеносных сосудов, так называемая «голова медузы».",difficulty:"medium",tags:["цирроз","симптомы"]},{id:"liver-048",topicId:"liver",question:"Какой характерный запах изо рта описан среди симптомов цирроза?",options:["Запах ацетона","Запах аммиака","Гнилостный запах","Запах ментола"],correctIndex:3,explanation:"Среди общих симптомов цирроза указан запах ментола из ротовой полости.",difficulty:"hard",tags:["цирроз","симптомы"]},{id:"liver-049",topicId:"liver",question:"Что такое печёночная энцефалопатия?",options:["Потенциально обратимое нарушение работы мозга из-за неспособности печени очищать кровь от токсинов","Необратимое разрушение ткани печени","Воспаление оболочек головного мозга","Опухолевое поражение печени с метастазами в мозг"],correctIndex:0,explanation:"Печёночная энцефалопатия — потенциально обратимое нарушение работы мозга, возникающее из-за того, что повреждённая печень не может очищать кровь от токсинов.",difficulty:"hard",tags:["цирроз","осложнения"]},{id:"liver-050",topicId:"liver",question:"Накопление какого токсина в первую очередь вызывает печёночную энцефалопатию?",options:["Билирубина","Аммиака","Мочевины","Холестерина"],correctIndex:1,explanation:"Печёночная энцефалопатия возникает из-за неспособности печени очищать кровь от токсинов, в первую очередь от аммиака.",difficulty:"hard",tags:["цирроз","патогенез"]},{id:"liver-051",topicId:"liver",question:"Что такое гепатостеатоз?",options:["Воспаление желчных протоков","Замещение печёночной ткани рубцовой","Избыточное накопление жира в клетках печени","Опухоль печени доброкачественного характера"],correctIndex:2,explanation:"Гепатостеатоз (жировой гепатоз, «ожирение печени») — это избыточное накопление жира в клетках печени.",difficulty:"medium",tags:["гепатостеатоз","определение"]},{id:"liver-052",topicId:"liver",question:"Какие факторы являются основными причинами гепатостеатоза?",options:["Переохлаждение и стресс","Наследственные ферментопатии","Приём антибиотиков","Избыточный вес, сахарный диабет 2 типа, высокий холестерин и злоупотребление алкоголем"],correctIndex:3,explanation:"Основные причины гепатостеатоза — избыточный вес, сахарный диабет 2 типа, высокий уровень холестерина и злоупотребление алкоголем.",difficulty:"medium",tags:["гепатостеатоз","этиология"]},{id:"liver-053",topicId:"liver",question:"Какие показатели относятся к печёночным пробам?",options:["АЛТ и АСТ","СОЭ и СРБ","WBC и RBC","HbA1c и глюкоза"],correctIndex:0,explanation:"Печёночные пробы включают АЛТ и АСТ.",difficulty:"medium",tags:["диагностика"]},{id:"liver-054",topicId:"liver",question:"Какой показатель свёртываемости крови входит в лабораторную диагностику болезней печени?",options:["D-димер","Фибриноген","МНО эритроцитов","Гематокрит"],correctIndex:1,explanation:"В лабораторную диагностику входит фибриноген — фактор свёртываемости крови, а также определение протромбинового индекса.",difficulty:"hard",tags:["диагностика"]},{id:"liver-055",topicId:"liver",question:"Какой метод инструментальной диагностики оценивает плотность и эластичность тканей печени?",options:["Ангиография","ФЭГДС","Эластометрия (эластография)","Пункционная биопсия"],correctIndex:2,explanation:"Эластометрия/эластография — анализ плотности и эластичности тканей.",difficulty:"hard",tags:["диагностика"]},{id:"liver-056",topicId:"liver",question:"Какой инструментальный метод применяется для оценки печёночного кровотока?",options:["Колоноскопия","Эластография","Пункционная биопсия","Ангиография"],correctIndex:3,explanation:"Ангиография применяется для оценки печёночного кровотока.",difficulty:"medium",tags:["диагностика"]},{id:"liver-057",topicId:"liver",question:"Что входит в лечение заболеваний печени?",options:["Гепатопротекторы, витаминные комплексы, средства для оттока желчи и антигельминтные препараты при паразитах","Только антибиотики широкого спектра","Только хирургическое удаление части органа","Только ингибиторы протонной помпы"],correctIndex:0,explanation:"Лечение включает гепатопротекторы, витаминные комплексы, средства для оттока желчи и антигельминтные препараты, если причина поражения — паразиты.",difficulty:"medium",tags:["лечение"]},{id:"liver-058",topicId:"liver",question:"Что такое гепатопротекторы?",options:["Средства, усиливающие выработку желчи","Группа лекарственных средств для защиты и восстановления клеток печени","Препараты, снижающие уровень билирубина в крови","Средства, разрушающие вирусы гепатита"],correctIndex:1,explanation:"Гепатопротекторы — группа лекарственных средств, предназначенных для защиты и восстановления клеток печени (гепатоцитов).",difficulty:"medium",tags:["гепатопротекторы","определение"]},{id:"liver-059",topicId:"liver",question:"При каких поражениях печени применяются гепатопротекторы?",options:["Только при вирусных","Только при жировых","При токсических, вирусных и жировых поражениях","Только при опухолевых"],correctIndex:2,explanation:"Гепатопротекторы применяются при токсических, вирусных и жировых поражениях печени.",difficulty:"medium",tags:["гепатопротекторы","показания"]},{id:"liver-060",topicId:"liver",question:"Какое действие оказывают эссенциальные фосфолипиды?",options:["Усиливают выработку желчи","Снижают уровень глюкозы крови","Уничтожают вирусы в гепатоцитах","Восстанавливают структуру мембран клеток печени"],correctIndex:3,explanation:"Эссенциальные фосфолипиды восстанавливают структуру мембран гепатоцитов.",difficulty:"medium",tags:["гепатопротекторы","препараты"]},{id:"liver-061",topicId:"liver",question:"Какое действующее вещество относится к гепатопротекторам?",options:["Адеметионин","Омепразол","Лоперамид","Метоклопрамид"],correctIndex:0,explanation:"Адеметионин относится к гепатопротекторам наряду с эссенциальными фосфолипидами, силимарином, глутатионом, L-орнитин-L-аспартатом и липоевой кислотой.",difficulty:"medium",tags:["гепатопротекторы","препараты"]},{id:"liver-062",topicId:"liver",question:"Укажите гепатопротектор среди приведённых наименований.",options:["Панкреатин","Липоевая кислота","Бисакодил","Ондансетрон"],correctIndex:1,explanation:"Липоевая кислота входит в перечень гепатопротекторов.",difficulty:"medium",tags:["гепатопротекторы","препараты"]},{id:"liver-063",topicId:"liver",question:"Какое действующее вещество из гепатопротекторов представляет собой аминокислотную комбинацию?",options:["Силимарин","Глутатион","L-орнитин-L-аспартат","Адеметионин"],correctIndex:2,explanation:"В перечне гепатопротекторов указан L-орнитин-L-аспартат.",difficulty:"hard",tags:["гепатопротекторы","препараты"]},{id:"liver-064",topicId:"liver",question:"Обмен каких веществ регулирует печень в рамках метаболической функции?",options:["Только углеводов","Только белков","Только жиров","Углеводов, жиров и белков"],correctIndex:3,explanation:"Метаболическая функция печени регулирует обмен углеводов, жиров (синтез холестерина) и белков.",difficulty:"medium",tags:["физиология","функции"]}];export{i as default};
